CREATE OR REPLACE FUNCTION public.content_erasure_capture_copy(payload jsonb, result jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
